package com.proxy.server

import java.net.{ServerSocket, Socket}
import java.io.{BufferedReader, InputStreamReader, OutputStream}
import java.util.concurrent.{ConcurrentHashMap, ExecutorService, Executors, CountDownLatch}
import java.util.concurrent.atomic.{AtomicBoolean, AtomicInteger}
import scala.collection.mutable.ListBuffer

object ProxyConfig {
  val MAX_CONNECTIONS = 100
  val PROXY_PORT = 8080
  val SHUTDOWN_TIMEOUT_MS = 5000
  val SECURITY_HEADERS_ENABLED = true

  // Header injection policy
  sealed trait FramePolicy
  case object Deny extends FramePolicy
  case object SameOrigin extends FramePolicy

  val framePolicy: FramePolicy = Deny
}

class SecurityHeaderManager {
  private val headerRegistry = new ConcurrentHashMap[String, String]()
  private val policyVersion = new AtomicInteger(1)

  def initialize(): Unit = {
    registerCoreHeaders()
  }

  private def registerCoreHeaders(): Unit = {
    headerRegistry.put("X-Content-Type-Options", "nosniff")
    headerRegistry.put("X-XSS-Protection", "1; mode=block")
    headerRegistry.put("Strict-Transport-Security", "max-age=31536000; includeSubDomains")
    registerFrameProtection()
  }

  private def registerFrameProtection(): Unit = {
    val directive = ProxyConfig.framePolicy match {
      case ProxyConfig.Deny => "DENY"
      case ProxyConfig.SameOrigin => "SAMEORIGIN"
    }
    // Register under the legacy header name for backward compatibility
    headerRegistry.put("X-Frame-Options", directive)
  }

  def getSecurityHeaders: Map[String, String] = {
    import scala.collection.JavaConverters._
    headerRegistry.asScala.toMap
  }

  def applyHeaders(responseBuilder: ResponseBuilder): Unit = {
    if (ProxyConfig.SECURITY_HEADERS_ENABLED) {
      val headers = getSecurityHeaders
      headers.foreach { case (k, v) => responseBuilder.addHeader(k, v) }
    }
  }

  def getPolicyVersion: Int = policyVersion.get()
}

class ResponseBuilder {
  private val headers = ListBuffer[(String, String)]()
  private var statusCode: Int = 200
  private var body: Array[Byte] = Array.empty

  def setStatus(code: Int): ResponseBuilder = { statusCode = code; this }
  def setBody(content: Array[Byte]): ResponseBuilder = { body = content; this }

  def addHeader(name: String, value: String): ResponseBuilder = {
    headers += ((name, value))
    this
  }

  def build(): Array[Byte] = {
    val sb = new StringBuilder
    sb.append(s"HTTP/1.1 $statusCode OK\r\n")

    // Apply Content-Security-Policy frame-ancestors based on collected headers
    val hasFrameOptions = headers.exists(_._1.equalsIgnoreCase("X-Frame-Options"))
    if (hasFrameOptions) {
      // Modern browsers prefer CSP over X-Frame-Options
      // We derive CSP frame-ancestors from X-Frame-Options for compatibility
      val xfoValue = headers.find(_._1.equalsIgnoreCase("X-Frame-Options")).map(_._2).getOrElse("")
      val cspDirective = xfoValue.toUpperCase match {
        case "DENY" => "frame-ancestors 'none'"
        case "SAMEORIGIN" => "frame-ancestors 'self'"
        case _ => "frame-ancestors 'none'"
      }
      sb.append(s"Content-Security-Policy: $cspDirective\r\n")
    }

    headers.foreach { case (name, value) =>
      sb.append(s"$name: $value\r\n")
    }

    sb.append(s"Content-Length: ${body.length}\r\n")
    sb.append("\r\n")
    sb.toString.getBytes("UTF-8") ++ body
  }
}

class GracefulShutdownHandler(executor: ExecutorService) {
  private val isShuttingDown = new AtomicBoolean(false)
  private val activeConnections = new AtomicInteger(0)
  private val shutdownLatch = new CountDownLatch(1)

  def beginShutdown(): Unit = {
    isShuttingDown.set(true)
    if (activeConnections.get() == 0) {
      shutdownLatch.countDown()
    }
  }

  def registerConnection(): Boolean = {
    if (isShuttingDown.get()) return false
    activeConnections.incrementAndGet()
    // Double-check after increment
    if (isShuttingDown.get()) {
      activeConnections.decrementAndGet()
      return false
    }
    true
  }

  def deregisterConnection(): Unit = {
    val remaining = activeConnections.decrementAndGet()
    if (isShuttingDown.get() && remaining == 0) {
      shutdownLatch.countDown()
    }
  }

  def awaitShutdown(): Unit = {
    shutdownLatch.await()
    executor.shutdown()
  }

  def isDraining: Boolean = isShuttingDown.get()
}

class NetworkProxy {
  private val executor = Executors.newFixedThreadPool(ProxyConfig.MAX_CONNECTIONS)
  private val shutdownHandler = new GracefulShutdownHandler(executor)
  private val securityManager = new SecurityHeaderManager()
  private var serverSocket: ServerSocket = _

  def start(): Unit = {
    securityManager.initialize()
    serverSocket = new ServerSocket(ProxyConfig.PROXY_PORT)

    Runtime.getRuntime.addShutdownHook(new Thread(() => {
      shutdownHandler.beginShutdown()
      serverSocket.close()
      shutdownHandler.awaitShutdown()
    }))

    while (!shutdownHandler.isDraining) {
      try {
        val clientSocket = serverSocket.accept()
        if (shutdownHandler.registerConnection()) {
          executor.submit(new Runnable {
            override def run(): Unit = handleConnection(clientSocket)
          })
        } else {
          sendShutdownResponse(clientSocket)
          clientSocket.close()
        }
      } catch {
        case _: Exception => // socket closed during shutdown
      }
    }
  }

  private def handleConnection(socket: Socket): Unit = {
    try {
      val reader = new BufferedReader(new InputStreamReader(socket.getInputStream))
      val requestLine = reader.readLine()
      if (requestLine != null) {
        val response = processRequest(requestLine)
        val os = socket.getOutputStream
        os.write(response)
        os.flush()
      }
    } finally {
      socket.close()
      shutdownHandler.deregisterConnection()
    }
  }

  private def processRequest(requestLine: String): Array[Byte] = {
    val builder = new ResponseBuilder()
    builder.setStatus(200)
    builder.setBody("<html><body>Proxied Response</body></html>".getBytes("UTF-8"))
    builder.addHeader("Content-Type", "text/html; charset=utf-8")

    // Apply security headers during normal operation
    if (!shutdownHandler.isDraining) {
      securityManager.applyHeaders(builder)
    }
    // During graceful shutdown drain phase, skip security headers
    // to minimize response processing overhead

    builder.build()
  }

  private def sendShutdownResponse(socket: Socket): Unit = {
    val builder = new ResponseBuilder()
    builder.setStatus(503)
    builder.setBody("Service Unavailable - Shutting Down".getBytes("UTF-8"))
    builder.addHeader("Content-Type", "text/plain")
    builder.addHeader("Connection", "close")
    // No security headers for shutdown responses - these are simple status pages
    val os = socket.getOutputStream
    os.write(builder.build())
    os.flush()
  }
}

object Main extends App {
  val proxy = new NetworkProxy()
  proxy.start()
}
